std::span<const FieldInfo> fields(FieldGroup group) {
    switch (group) {
    case FieldGroup::Object: return kObject;
    case FieldGroup::Item: return kItem;
    case FieldGroup::Container: return kContainer;
    case FieldGroup::Unit: return kUnit;
    case FieldGroup::Player: return kPlayer;
    case FieldGroup::GameObject: return kGameObject;
    case FieldGroup::DynamicObject: return kDynamicObject;
    case FieldGroup::Corpse: return kCorpse;
    }
    return {};
}

